"use client";

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@clerk/nextjs';

/**
 * RedirectToDashboard component
 * A simple component that redirects to the dashboard immediately
 */
const RedirectToDashboard = () => {
  const router = useRouter();
  const { isLoaded, isSignedIn } = useAuth();
  const [redirectAttempted, setRedirectAttempted] = useState(false);
  const [redirectStatus, setRedirectStatus] = useState('Initializing...');

  useEffect(() => {
    if (!isLoaded) {
      setRedirectStatus('Loading authentication state...');
      return;
    }

    if (!redirectAttempted) {
      setRedirectAttempted(true);

      if (isSignedIn) {
        setRedirectStatus('Authentication confirmed. Redirecting to dashboard...');

        // Add a small delay to ensure the auth state is fully processed
        setTimeout(() => {
          try {
            console.log("RedirectToDashboard: Redirecting to dashboard");

            // Use window.location for a hard redirect to ensure it works
            window.location.href = '/dashboard';

            // Also try the router as a fallback
            router.push('/dashboard');
          } catch (error) {
            console.error("Error during redirect:", error);
            setRedirectStatus('Redirect failed. Please use the link below.');
          }
        }, 500);
      } else {
        setRedirectStatus('Not authenticated. Redirecting to sign-in...');

        // Redirect to sign-in if not authenticated
        setTimeout(() => {
          try {
            window.location.href = '/sign-in?redirect_url=/dashboard';
          } catch (error) {
            console.error("Error during redirect to sign-in:", error);
            setRedirectStatus('Redirect failed. Please use the link below.');
          }
        }, 500);
      }
    }
  }, [isLoaded, isSignedIn, router, redirectAttempted]);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen p-4">
      <div className="bg-gray-800 p-6 rounded-lg shadow-lg max-w-md w-full text-center">
        <h1 className="text-2xl font-bold text-white mb-4">Redirecting...</h1>
        <p className="text-gray-300">{redirectStatus}</p>
        <div className="mt-4">
          <div className="w-12 h-12 border-t-4 border-blue-500 border-solid rounded-full animate-spin mx-auto"></div>
        </div>
        <div className="mt-6 space-y-2">
          <p className="text-gray-400">
            If you are not redirected automatically:
          </p>
          <div className="flex flex-col space-y-2">
            <a
              href="/dashboard"
              className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md transition-colors"
            >
              Go to Dashboard
            </a>
            <a
              href="/sign-in?redirect_url=/dashboard"
              className="px-4 py-2 bg-gray-600 hover:bg-gray-700 text-white rounded-md transition-colors"
            >
              Go to Sign In
            </a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RedirectToDashboard;
